def gen(rng):
    def ser(val, L, R):
        out = []
        q = [0]
        i = 0
        while i < len(q):
            u = q[i]
            i += 1
            if u < 0:
                out.append('null')
                continue
            out.append(str(val[u]))
            q.append(L[u])
            q.append(R[u])
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def build(n, mode, lo, hi):
        val = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        if mode == 'random':
            slots = [(0, 0), (0, 1)]
            for v in range(1, n):
                j = rng.randrange(len(slots))
                slots[j], slots[-1] = slots[-1], slots[j]
                u, side = slots.pop()
                (L if side == 0 else R)[u] = v
                slots.append((v, 0))
                slots.append((v, 1))
        elif mode == 'chain':
            for v in range(1, n):
                (L if rng.random() < 0.5 else R)[v - 1] = v
        elif mode == 'left':
            for v in range(1, n):
                L[v - 1] = v
        else:  # complete
            for v in range(1, n):
                (L if v % 2 == 1 else R)[(v - 1) // 2] = v
        return ser(val, L, R)

    tests = ['-5', '7', '1 2 3', '-3 -1 -2', '2 -1 -2', '-10 9 20 null null 15 7',
             '1 -2 3 4 5 -6 2', '5 4 8 11 null 13 4 7 2 null null null 1']
    for n, lo, hi in ((4, -5, 5), (7, -9, 9), (10, -20, 20), (12, -50, 10), (15, -3, 30), (9, -100, -1), (14, -1000, 1000)):
        tests.append(build(n, 'random', lo, hi))
    tests.append(build(60, 'random', -1000, 1000))
    tests.append(build(50000, 'random', -1000, 1000))
    tests.append(build(50000, 'complete', -1000, 1000))
    tests.append(build(50000, 'chain', -1000, 1000))
    tests.append(build(50000, 'left', -1000, -1))
    tests.append(build(50000, 'left', 1, 1000))
    tests.append(build(50000, 'random', -1000, 400))
    return tests

